const defaultGarrafaBase64 = 'data:image/jpeg;base64,';
const defaultLogoBase64 = 'data:image/png;base64,';
// State variables
let slideTitle = "JUEVES 30 DE JULIO 2026";
let neighborhoods = ["PRIMERO DE MAYO", "EMANUEL", "SAN FELIPE", "FRONTERA"];
let logoPosition = "top-right";
let colorTheme = "spc-blue";
let overlayBrightness = 45;
let bgBlur = 0;
let textCase = "uppercase";
let fontFamily = "Montserrat";

// Theme configuration details for Canvas render
const themes = {
  "spc-blue": { accent: "#00bcd4", accentRgb: "0, 188, 212" },
  "dark-gold": { accent: "#ffb300", accentRgb: "255, 179, 0" },
  "crimson": { accent: "#e53935", accentRgb: "229, 57, 21" },
  "emerald": { accent: "#43a047", accentRgb: "67, 160, 71" },
  "glass-dark": { accent: "#e0e0e0", accentRgb: "224, 224, 224" }
};

// DOM Selectors
const docTitleInput = document.getElementById("slide-title");
const btnToday = document.getElementById("btn-today");
const neighborhoodInput = document.getElementById("neighborhood-input");
const btnAddNeighborhood = document.getElementById("btn-add-neighborhood");
const tagsList = document.getElementById("tags-list");

const selectLogoPos = document.getElementById("logo-position");
const selectTheme = document.getElementById("color-theme");
const sliderBrightness = document.getElementById("overlay-brightness");
const valBrightness = document.getElementById("val-brightness");
const sliderBlur = document.getElementById("bg-blur");
const valBlur = document.getElementById("val-blur");
const selectTextCase = document.getElementById("text-case");
const selectFontFamily = document.getElementById("font-family");

const btnDownload = document.getElementById("btn-download");
const inputCustomBg = document.getElementById("custom-bg-input");
const inputCustomLogo = document.getElementById("custom-logo-input");

// Preview Elements
const previewFrame = document.getElementById("slide-preview-frame");
const previewBg = document.getElementById("preview-bg");
const previewOverlay = document.getElementById("preview-overlay");
const previewLogoContainer = document.getElementById("preview-logo-container");
const previewTitleBar = document.getElementById("preview-title-bar");
const previewTitle = document.getElementById("preview-title");
const previewColumnsGrid = document.getElementById("preview-columns-grid");

// Password Lock & Config Panel DOM Selectors
const controlPanel = document.getElementById("control-panel");
const btnToggleConfig = document.getElementById("btn-toggle-config");
const btnLockSidebar = document.getElementById("btn-lock-sidebar");
const passwordModal = document.getElementById("password-modal");
const passwordInput = document.getElementById("password-input");
const btnPasswordSubmit = document.getElementById("btn-password-submit");
const btnPasswordCancel = document.getElementById("btn-password-cancel");
const btnTogglePasswordVisibility = document.getElementById("btn-toggle-password-visibility");
const passwordErrorMsg = document.getElementById("password-error-msg");
const eyeOpenIcon = document.getElementById("eye-open-icon");
const eyeClosedIcon = document.getElementById("eye-closed-icon");

// Publication Scheduling & Batch DOM Selectors
const datePickerInput = document.getElementById("date-picker-input");
const scheduleRecommendation = document.getElementById("schedule-recommendation");
const batchStartDate = document.getElementById("batch-start-date");
const batchEndDate = document.getElementById("batch-end-date");
const btnGenerateBatch = document.getElementById("btn-generate-batch");

// Header actions download button
const btnDownloadHeader = document.getElementById("btn-download-header");

// Selected Date reference for single plate
let currentPlateDate = new Date(2026, 6, 30); // Default: July 30, 2026

// Password Constant
const SECRET_PASSWORD = "4206371Luis*";

function lockSidebar() {
  controlPanel.classList.add("collapsed");
}

function unlockSidebar() {
  controlPanel.classList.remove("collapsed");
}

function openPasswordModal() {
  passwordInput.value = "";
  passwordErrorMsg.classList.remove("active");
  passwordModal.classList.add("active");
  setTimeout(() => passwordInput.focus(), 100);
}

function closePasswordModal() {
  passwordModal.classList.remove("active");
  passwordErrorMsg.classList.remove("active");
}

function verifyPassword() {
  if (passwordInput.value === SECRET_PASSWORD) {
    closePasswordModal();
    unlockSidebar();
  } else {
    passwordErrorMsg.classList.add("active");
    passwordInput.select();
  }
}

// Image references for Canvas export
const bgImage = new Image();
bgImage.src = typeof defaultGarrafaBase64 !== "undefined" ? defaultGarrafaBase64 : "GARRAFA.jpg";
const logoImage = new Image();
logoImage.src = typeof defaultLogoBase64 !== "undefined" ? defaultLogoBase64 : "LOGO  SPC.png";

// Initialize Page
window.addEventListener("DOMContentLoaded", () => {
  renderTags();
  
  // Set default values for dates
  const today = new Date();
  const yyyy = today.getFullYear();
  const mm = String(today.getMonth() + 1).padStart(2, '0');
  const dd = String(today.getDate()).padStart(2, '0');
  
  if (datePickerInput) datePickerInput.value = "2026-07-30"; // default value match
  if (batchStartDate) batchStartDate.value = `${yyyy}-${mm}-${dd}`;
  
  const nextWeek = new Date(today);
  nextWeek.setDate(today.getDate() + 7);
  const nyyyy = nextWeek.getFullYear();
  const nmm = String(nextWeek.getMonth() + 1).padStart(2, '0');
  const ndd = String(nextWeek.getDate()).padStart(2, '0');
  if (batchEndDate) batchEndDate.value = `${nyyyy}-${nmm}-${ndd}`;

  updatePreview();
  setupEventListeners();
  updateScheduleRecommendation();
});

// Event Listeners setup
function setupEventListeners() {
  // 1. Title/Date inputs
  docTitleInput.addEventListener("input", (e) => {
    slideTitle = e.target.value;
    updatePreview();
  });

  btnToday.addEventListener("click", () => {
    const today = new Date();
    currentPlateDate = today;
    const formatted = getFormattedSpanishDate(today);
    docTitleInput.value = formatted;
    slideTitle = formatted;
    
    // Format YYYY-MM-DD for date input
    const yyyy = today.getFullYear();
    const mm = String(today.getMonth() + 1).padStart(2, '0');
    const dd = String(today.getDate()).padStart(2, '0');
    if (datePickerInput) datePickerInput.value = `${yyyy}-${mm}-${dd}`;
    
    updatePreview();
    updateScheduleRecommendation();
  });

  // date picker input
  if (datePickerInput) {
    datePickerInput.addEventListener("change", (e) => {
      if (e.target.value) {
        const parts = e.target.value.split("-");
        const selectedDate = new Date(parts[0], parts[1] - 1, parts[2]);
        currentPlateDate = selectedDate;
        const formatted = getFormattedSpanishDate(selectedDate);
        docTitleInput.value = formatted;
        slideTitle = formatted;
        updatePreview();
        updateScheduleRecommendation();
      }
    });
  }

  // Batch generation trigger
  if (btnGenerateBatch) {
    btnGenerateBatch.addEventListener("click", async () => {
      const startVal = batchStartDate.value;
      const endVal = batchEndDate.value;
      if (!startVal || !endVal) {
        alert("Por favor, seleccione fecha de inicio y fin para el lote.");
        return;
      }
      
      const startParts = startVal.split("-");
      const endParts = endVal.split("-");
      
      let start = new Date(startParts[0], startParts[1] - 1, startParts[2]);
      const end = new Date(endParts[0], endParts[1] - 1, endParts[2]);
      
      if (start > end) {
        alert("La fecha de inicio debe ser anterior o igual a la fecha de fin.");
        return;
      }
      
      const checkboxes = document.querySelectorAll(".day-checkbox input[type='checkbox']");
      const selectedDays = Array.from(checkboxes).filter(cb => cb.checked).map(cb => parseInt(cb.value));
      
      if (selectedDays.length === 0) {
        alert("Debe seleccionar al menos un día de la semana.");
        return;
      }
      
      btnGenerateBatch.disabled = true;
      btnGenerateBatch.textContent = "Generando...";
      
      const datesToGenerate = [];
      let tempDate = new Date(start);
      while (tempDate <= end) {
        const dayOfWeek = tempDate.getDay();
        if (selectedDays.includes(dayOfWeek)) {
          datesToGenerate.push(new Date(tempDate));
        }
        tempDate.setDate(tempDate.getDate() + 1);
      }
      
      if (datesToGenerate.length === 0) {
        alert("No hay días coincidentes con su selección en el rango de fechas.");
        btnGenerateBatch.disabled = false;
        btnGenerateBatch.textContent = "⚡ Generar Lote de Placas";
        return;
      }
      
      let count = 0;
      for (let i = 0; i < datesToGenerate.length; i++) {
        const d = datesToGenerate[i];
        const formatted = getFormattedSpanishDate(d);
        
        slideTitle = formatted;
        updatePreview();
        
        downloadJPG();
        
        await new Promise(resolve => setTimeout(resolve, 250));
        count++;
      }
      
      const singleParts = datePickerInput.value.split("-");
      currentPlateDate = new Date(singleParts[0], singleParts[1] - 1, singleParts[2]);
      slideTitle = getFormattedSpanishDate(currentPlateDate);
      updatePreview();
      updateScheduleRecommendation();
      
      btnGenerateBatch.disabled = false;
      btnGenerateBatch.textContent = "⚡ Generar Lote de Placas";
      alert(`Se han generado e iniciado la descarga de ${count} placas con éxito.`);
    });
  }

  // 2. Neighborhood inputs
  neighborhoodInput.addEventListener("keydown", (e) => {
    if (e.key === "Enter" || e.key === ",") {
      e.preventDefault();
      addNeighborhoodFromInput();
    }
  });

  btnAddNeighborhood.addEventListener("click", addNeighborhoodFromInput);

  // 3. Design controls
  selectLogoPos.addEventListener("change", (e) => {
    logoPosition = e.target.value;
    updatePreview();
  });

  selectTheme.addEventListener("change", (e) => {
    colorTheme = e.target.value;
    updatePreview();
  });

  sliderBrightness.addEventListener("input", (e) => {
    overlayBrightness = parseInt(e.target.value);
    valBrightness.textContent = overlayBrightness;
    updatePreview();
  });

  sliderBlur.addEventListener("input", (e) => {
    bgBlur = parseInt(e.target.value);
    valBlur.textContent = bgBlur;
    updatePreview();
  });

  selectTextCase.addEventListener("change", (e) => {
    textCase = e.target.value;
    updatePreview();
  });

  selectFontFamily.addEventListener("change", (e) => {
    fontFamily = e.target.value;
    updatePreview();
  });

  // Custom uploads
  if (inputCustomBg) {
    inputCustomBg.addEventListener("change", (e) => {
      handleImageUpload(e.target.files[0], (dataUrl) => {
        bgImage.src = dataUrl;
        updatePreview();
      });
    });
  }

  if (inputCustomLogo) {
    inputCustomLogo.addEventListener("change", (e) => {
      handleImageUpload(e.target.files[0], (dataUrl) => {
        logoImage.src = dataUrl;
        updatePreview();
      });
    });
  }

  // 4. Download action
  btnDownload.addEventListener("click", downloadJPG);
  if (btnDownloadHeader) {
    btnDownloadHeader.addEventListener("click", downloadJPG);
  }

  // 5. Lock/Unlock Sidebar event listeners
  if (btnToggleConfig) {
    btnToggleConfig.addEventListener("click", () => {
      if (controlPanel.classList.contains("collapsed")) {
        openPasswordModal();
      } else {
        lockSidebar();
      }
    });
  }

  if (btnLockSidebar) {
    btnLockSidebar.addEventListener("click", () => {
      lockSidebar();
    });
  }

  if (btnPasswordCancel) {
    btnPasswordCancel.addEventListener("click", () => {
      closePasswordModal();
    });
  }

  if (passwordModal) {
    // Close modal when clicking outside card
    passwordModal.addEventListener("click", (e) => {
      if (e.target === passwordModal) {
        closePasswordModal();
      }
    });
  }

  if (btnPasswordSubmit) {
    btnPasswordSubmit.addEventListener("click", () => {
      verifyPassword();
    });
  }

  if (passwordInput) {
    passwordInput.addEventListener("keydown", (e) => {
      if (e.key === "Enter") {
        e.preventDefault();
        verifyPassword();
      }
    });
  }

  if (btnTogglePasswordVisibility) {
    btnTogglePasswordVisibility.addEventListener("click", () => {
      if (passwordInput.type === "password") {
        passwordInput.type = "text";
        eyeOpenIcon.classList.add("hide");
        eyeClosedIcon.classList.remove("hide");
      } else {
        passwordInput.type = "password";
        eyeOpenIcon.classList.remove("hide");
        eyeClosedIcon.classList.add("hide");
      }
    });
  }
}

function handleImageUpload(file, callback) {
  if (file) {
    const reader = new FileReader();
    reader.onload = (e) => {
      callback(e.target.result);
    };
    reader.readAsDataURL(file);
  }
}

// Add Neighborhood from Text Input
function addNeighborhoodFromInput() {
  const val = neighborhoodInput.value.trim();
  if (val) {
    // Split by comma in case multiple are entered at once
    const parts = val.split(",").map(p => p.trim()).filter(p => p.length > 0);
    parts.forEach(part => {
      // Avoid duplicate tags
      if (!neighborhoods.includes(part)) {
        neighborhoods.push(part);
      }
    });
    neighborhoodInput.value = "";
    renderTags();
    updatePreview();
  }
}

// Render Neighborhood Tags in Editor
function renderTags() {
  tagsList.innerHTML = "";
  neighborhoods.forEach((item, index) => {
    const badge = document.createElement("div");
    badge.className = "tag-badge";
    badge.innerHTML = `
      <span>${item}</span>
      <button class="btn-remove-tag" data-index="${index}">&times;</button>
    `;
    tagsList.appendChild(badge);
  });

  // Attach delete click listeners
  document.querySelectorAll(".btn-remove-tag").forEach(btn => {
    btn.addEventListener("click", (e) => {
      const idx = parseInt(e.target.getAttribute("data-index"));
      neighborhoods.splice(idx, 1);
      renderTags();
      updatePreview();
    });
  });
}

// Sync State with Live Preview DOM Elements
function updatePreview() {
  // Update theme class on preview frame
  previewFrame.className = `slide-preview-frame theme-${colorTheme}`;

  // CSS variables update
  const selectedTheme = themes[colorTheme];
  previewFrame.style.setProperty("--accent-color", selectedTheme.accent);
  previewFrame.style.setProperty("--accent-color-rgb", selectedTheme.accentRgb);

  // Background and overlay values
  previewBg.style.backgroundImage = `url('${bgImage.src}')`;
  previewBg.style.filter = `blur(${bgBlur}px)`;
  previewOverlay.style.opacity = overlayBrightness / 100;

  // Logo source rendering
  const previewLogo = document.getElementById("preview-logo");
  if (previewLogo) {
    previewLogo.src = logoImage.src;
  }

  // Title rendering
  previewTitle.textContent = slideTitle;
  previewTitle.style.fontFamily = fontFamily === "Montserrat" ? "'Montserrat', sans-serif" :
                                 fontFamily === "Outfit" ? "'Outfit', sans-serif" : "Arial Black, sans-serif";

  // Logo position rendering
  previewLogoContainer.className = "slide-logo-container"; // reset
  previewLogoContainer.classList.add(`logo-pos-${logoPosition}`);

  // Neighborhood cards grid render
  previewColumnsGrid.innerHTML = "";
  
  if (neighborhoods.length > 0) {
    const maxRows = Math.min(4, neighborhoods.length); // limit rows to max 4
    
    // Set grid layout to column-flow
    previewColumnsGrid.style.display = "grid";
    previewColumnsGrid.style.gridTemplateRows = `repeat(${maxRows}, 1fr)`;
    previewColumnsGrid.style.gridAutoFlow = "column";
    previewColumnsGrid.style.gridTemplateColumns = "none"; // reset horizontal
    previewColumnsGrid.style.gap = "12px 24px";
    
    // Calculate columns count
    const colsCount = Math.ceil(neighborhoods.length / 4);
    if (colsCount === 1) {
      previewColumnsGrid.style.maxWidth = "500px";
      previewColumnsGrid.style.margin = "0 auto";
    } else {
      previewColumnsGrid.style.maxWidth = "none";
      previewColumnsGrid.style.margin = "0";
    }

    neighborhoods.forEach(item => {
      const card = document.createElement("div");
      card.className = "slide-col-card vertical-card";
      
      const displayedText = textCase === "uppercase" ? item.toUpperCase() : item;
      card.innerHTML = `<span style="font-family: ${fontFamily === "Montserrat" ? "'Montserrat', sans-serif" : fontFamily === "Outfit" ? "'Outfit', sans-serif" : "Arial Black, sans-serif"}">${displayedText}</span>`;
      previewColumnsGrid.appendChild(card);
    });
  } else {
    // Empty state placeholder inside preview
    previewColumnsGrid.style.display = "block";
    previewColumnsGrid.style.maxWidth = "none";
    previewColumnsGrid.style.margin = "0";
    previewColumnsGrid.innerHTML = `<div style="color: rgba(255,255,255,0.4); text-align: center; font-size: 1.2rem; padding: 20px;">Sin barrios agregados</div>`;
  }
}

// Generate Spanish Date String (e.g., JUEVES 30 DE JULIO 2026)
function getFormattedSpanishDate(date) {
  const days = ["DOMINGO", "LUNES", "MARTES", "MIÃ‰RCOLES", "JUEVES", "VIERNES", "SÃBADO"];
  const months = ["ENERO", "FEBRERO", "MARZO", "ABRIL", "MAYO", "JUNIO", "JULIO", "AGOSTO", "SEPTIEMBRE", "OCTUBRE", "NOVIEMBRE", "DICIEMBRE"];
  
  const dayName = days[date.getDay()];
  const dayNum = date.getDate();
  const monthName = months[date.getMonth()];
  const year = date.getFullYear();
  
  return `${dayName} ${dayNum} DE ${monthName} ${year}`;
}

// Canvas-based JPG Exporter (1920x1080 Full HD)
function downloadJPG() {
  const canvas = document.getElementById("export-canvas");
  const ctx = canvas.getContext("2d");
  
  // Set dimensions explicitly
  const width = 1920;
  const height = 1080;
  canvas.width = width;
  canvas.height = height;

  // Wait for images to load (they are usually cached/loaded by DOM already)
  if (!bgImage.complete || !logoImage.complete) {
    alert("Cargando imÃ¡genes de fondo... Intenta de nuevo en un segundo.");
    return;
  }

  // Clear Canvas
  ctx.clearRect(0, 0, width, height);

  // 1. Draw Background Image (Cover Scale Aspect Ratio)
  ctx.save();
  if (bgBlur > 0) {
    ctx.filter = `blur(${bgBlur * 2.5}px)`; // slightly more blur on larger canvas
  }
  
  // Draw bg centered cover
  const imgAspect = bgImage.width / bgImage.height;
  const canvasAspect = width / height;
  let drawW, drawH, drawX, drawY;
  
  if (imgAspect > canvasAspect) {
    drawH = height;
    drawW = height * imgAspect;
    drawX = (width - drawW) / 2;
    drawY = 0;
  } else {
    drawW = width;
    drawH = width / imgAspect;
    drawX = 0;
    drawY = (height - drawH) / 2;
  }
  
  ctx.drawImage(bgImage, drawX, drawY, drawW, drawH);
  ctx.restore();

  // 2. Draw Dark Overlay
  ctx.fillStyle = `rgba(0, 0, 0, ${overlayBrightness / 100})`;
  ctx.fillRect(0, 0, width, height);

  // Get active theme colors
  const activeTheme = themes[colorTheme];
  const accentColor = activeTheme.accent;

  // Font choices mapping
  let fontName = "Montserrat";
  if (fontFamily === "Outfit") fontName = "Outfit";
  if (fontFamily === "Arial") fontName = "Arial Black";

  // 3. Draw Top Title/Date Bar
  ctx.save();
  ctx.shadowColor = "rgba(0, 0, 0, 0.4)";
  ctx.shadowBlur = 20;
  ctx.shadowOffsetY = 10;

  // Measure title bar size
  ctx.font = `800 38px ${fontName}`;
  const titleText = slideTitle.toUpperCase();
  const textWidth = ctx.measureText(titleText).width;
  
  const barPaddingH = 80;
  const barPaddingV = 22;
  const barW = Math.min(width * 0.85, textWidth + barPaddingH * 2);
  const barH = 38 + barPaddingV * 2;
  const barX = (width - barW) / 2;
  const barY = 70; // 6.5% top space

  // Gradient for background
  const barGrad = ctx.createLinearGradient(barX, barY, barX + barW, barY);
  // Hex to RGB conversion for transparent theme colors
  const r = parseInt(activeTheme.accentRgb.split(",")[0]);
  const g = parseInt(activeTheme.accentRgb.split(",")[1]);
  const b = parseInt(activeTheme.accentRgb.split(",")[2]);
  
  barGrad.addColorStop(0, `rgba(${r}, ${g}, ${b}, 0.95)`);
  barGrad.addColorStop(1, `rgba(${r}, ${g}, ${b}, 0.75)`);
  
  ctx.fillStyle = barGrad;
  
  // Draw rounded rect for Title Bar
  drawRoundedRect(ctx, barX, barY, barW, barH, 8);
  ctx.fill();
  
  // Draw white borders (Left & Right side)
  ctx.lineWidth = 6;
  ctx.strokeStyle = "#ffffff";
  
  ctx.beginPath();
  ctx.moveTo(barX, barY);
  ctx.lineTo(barX, barY + barH);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(barX + barW, barY);
  ctx.lineTo(barX + barW, barY + barH);
  ctx.stroke();
  ctx.restore();

  // Draw Title Text
  ctx.save();
  ctx.fillStyle = "#ffffff";
  ctx.font = `800 38px ${fontName}`;
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.shadowColor = "rgba(0, 0, 0, 0.5)";
  ctx.shadowBlur = 4;
  ctx.shadowOffsetY = 2;
  ctx.fillText(titleText, width / 2, barY + barH / 2);
  ctx.restore();

  // 4. Draw Logo SPC
  if (logoPosition !== "hidden") {
    ctx.save();
    const logoH = 1080 * 0.14; // 14% of height
    const logoW = logoH * (logoImage.naturalWidth / logoImage.naturalHeight || 2.2); // Fallback to 2.2 aspect ratio if not loaded
    
    let logoX, logoY;
    const margin = 1080 * 0.045; // 4.5% margin

    switch(logoPosition) {
      case "top-right":
        logoX = width - margin - logoW;
        logoY = margin;
        break;
      case "top-left":
        logoX = margin;
        logoY = margin;
        break;
      case "bottom-right":
        logoX = width - margin - logoW;
        logoY = height - margin - logoH;
        break;
      case "bottom-left":
        logoX = margin;
        logoY = height - margin - logoH;
        break;
    }

    // Shadow for logo
    ctx.shadowColor = "rgba(0, 0, 0, 0.5)";
    ctx.shadowBlur = 15;
    ctx.shadowOffsetY = 5;
    
    ctx.drawImage(logoImage, logoX, logoY, logoW, logoH);
    ctx.restore();
  }

  // 5. Draw Neighborhood Columns at the Bottom (Vertical Column Flow)
  if (neighborhoods.length > 0) {
    ctx.save();
    
    const maxRows = 4;
    const totalItems = neighborhoods.length;
    const colsCount = Math.ceil(totalItems / maxRows);
    const actualRows = Math.min(maxRows, totalItems);
    
    const wrapperW = width * 0.90; // 90% space width
    let wrapperX = width * 0.05; // Centered
    const gapX = 40; // Column gap
    const gapY = 16; // Row gap
    const cardH = 52; // Row card height on high-res canvas
    
    let cardW;
    if (colsCount === 1) {
      cardW = 850; // set standard centered width for 1 col
      wrapperX = (width - cardW) / 2;
    } else {
      cardW = (wrapperW - (gapX * (colsCount - 1))) / colsCount;
    }

    const wrapperH = actualRows * cardH + (actualRows - 1) * gapY;
    const wrapperY = 1005 - wrapperH; // Positioned up from Y=1005 (bottom margin)

    neighborhoods.forEach((item, index) => {
      const colIdx = Math.floor(index / maxRows);
      const rowIdx = index % maxRows;
      
      const cardX = wrapperX + colIdx * (cardW + gapX);
      const cardY = wrapperY + rowIdx * (cardH + gapY);
      
      // Shadow for cards
      ctx.shadowColor = "rgba(0, 0, 0, 0.5)";
      ctx.shadowBlur = 20;
      ctx.shadowOffsetY = 10;

      // Card Background (dark grey gradient)
      const cardGrad = ctx.createLinearGradient(cardX, cardY, cardX, cardY + cardH);
      cardGrad.addColorStop(0, "rgba(15, 20, 30, 0.95)");
      cardGrad.addColorStop(1, "rgba(25, 30, 45, 0.90)");
      ctx.fillStyle = cardGrad;
      
      drawRoundedRect(ctx, cardX, cardY, cardW, cardH, 6);
      ctx.fill();

      // Card Bottom Accent Border (Accent Theme Color)
      ctx.shadowBlur = 0; // Disable shadows for borders
      ctx.shadowOffsetY = 0;
      ctx.fillStyle = accentColor;
      
      const borderH = 4;
      ctx.beginPath();
      drawRoundedRectBottom(ctx, cardX, cardY + cardH - borderH, cardW, borderH, 6);
      ctx.fill();

      // Card Text (Centered)
      ctx.fillStyle = "#ffffff";
      
      const displayedText = textCase === "uppercase" ? item.toUpperCase() : item;
      
      const maxTextW = cardW * 0.9;
      let textToRender = displayedText;
      let fontSz = 30; // standard font size for 52px card
      ctx.font = `700 ${fontSz}px ${fontName}`;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.shadowColor = "rgba(0, 0, 0, 0.4)";
      ctx.shadowBlur = 4;
      ctx.shadowOffsetY = 2;
      
      // Dynamically shrink text size if it overflows card width
      while (ctx.measureText(textToRender).width > maxTextW && fontSz > 14) {
        fontSz -= 2;
        ctx.font = `700 ${fontSz}px ${fontName}`;
      }

      ctx.fillText(textToRender, cardX + cardW / 2, cardY + (cardH - borderH) / 2);
    });

    ctx.restore();
  }

  // Trigger Download
  const dateStr = slideTitle.replace(/\s+/g, "_").toLowerCase();
  const filename = `placa_spc_${dateStr}.jpg`;
  
  const link = document.createElement("a");
  link.download = filename;
  link.href = canvas.toDataURL("image/jpeg", 0.95);
  link.click();
}

// Rounded rect helper function
function drawRoundedRect(ctx, x, y, width, height, radius) {
  ctx.beginPath();
  ctx.moveTo(x + radius, y);
  ctx.lineTo(x + width - radius, y);
  ctx.quadraticCurveTo(x + width, y, x + width, y + radius);
  ctx.lineTo(x + width, y + height - radius);
  ctx.quadraticCurveTo(x + width, y + height, x + width - radius, y + height);
  ctx.lineTo(x + radius, y + height);
  ctx.quadraticCurveTo(x, y + height, x, y + height - radius);
  ctx.lineTo(x, y + radius);
  ctx.quadraticCurveTo(x, y, x + radius, y);
  ctx.closePath();
}

// Draw bottom-only rounded corners for card accent bar
function drawRoundedRectBottom(ctx, x, y, width, height, radius) {
  ctx.beginPath();
  ctx.moveTo(x, y);
  ctx.lineTo(x + width, y);
  ctx.lineTo(x + width, y + height - radius);
  ctx.quadraticCurveTo(x + width, y + height, x + width - radius, y + height);
  ctx.lineTo(x + radius, y + height);
  ctx.quadraticCurveTo(x, y + height, x, y + height - radius);
  ctx.closePath();
}

// Calculate schedule recommendation on load / date change
function updateScheduleRecommendation() {
  if (!currentPlateDate) return;
  const pubDate = new Date(currentPlateDate);
  pubDate.setDate(pubDate.getDate() - 1);
  const formattedPub = getFormattedSpanishDate(pubDate);
  const recommendationEl = document.getElementById("schedule-recommendation");
  if (recommendationEl) {
    recommendationEl.textContent = `${formattedPub} a las 15:00 hs.`;
  }
}
